program.# The query buttons on their panel. Each:
# Kyselypainikkeet paneelissaan. Jokainen lähettää kuvakaappauksen Googleen:
#   name: painikkeen vihje;
#   mode: minne kuvakaappaus menee:
#     "ai": Googlen tekoäly vastaa minikehotteeseen sanoin kuvan ja kysymyksen
#       tulosten yläpuolella;
#     "chat": itse tekoälytila (google.com/ai) ohjelman ikkunassa: ohjelma vie sinne
#       kuvakaappauksen ja kysymyksen ja lähettää ne; ikkuna tulee esiin valinnan viereen
#       pelkän keskustelun ja seuraavan kysymyksen kentän kanssa; pohjassa pidettynä
#       painike kysyy oman kysymyksen ääneen minikehotteen sijaan niin kauan kuin
#       sitä pidetään;
#     "answer": sama piilotetulla ikkunalla: vastaus näkyy kortissa valinnan
#       vieressä;
#     "images": kuvahaku ilman kysymystä, ohjelman ikkunassa valinnan vieressä:
#       heti tarkat osumat, sivut, joilla on juuri tämä kuva ja joiden otsikot
#       kertovat usein, kuka tai mikä siinä on;
#   prompt: minikehote, kysymys tekoälylle, tiloissa "ai", "chat" ja "answer";
#   key: painikkeen näppäin, kun näyttö on jäädytetty;
#   icon: "google", "translate", "images" tai "question".
# Tekoälyn painikkeet ovat paneelissa ensin, kuvahaku niiden jälkeen.
# Googleen kirjaudutaan ohjelman ikkunassa asetusikkunasta, ”Google-tili”; kun kukaan
# ei ole kirjautunut, ohjelma ehdottaa kirjautumista käynnistyessään.
